import React, { useId, useState } from 'react';

/**
 * The form primitives.
 *
 * Every control here pairs a real <label htmlFor> with an input id generated by
 * useId. That was the single biggest accessibility defect in the app: the form
 * had nine labels and not one of them was programmatically associated, and the
 * per-row quantity and price inputs had no accessible name at all.
 *
 * Each control also takes a `name`, so the fields are addressable by automated
 * agents and by browser autofill, and a stable `data-testid`.
 */

const CONTROL_CLASS =
  'w-full rounded-lg border border-border-strong bg-surface px-3 py-2.5 text-sm text-fg ' +
  'placeholder:text-fg-muted transition-colors hover:border-brand ' +
  'disabled:cursor-not-allowed disabled:opacity-60';

interface FieldShellProps {
  label: string;
  hint?: string;
  htmlFor: string;
  children: React.ReactNode;
  className?: string;
}

const FieldShell: React.FC<FieldShellProps> = ({ label, hint, htmlFor, children, className }) => (
  <div className={className}>
    <label htmlFor={htmlFor} className="mb-1.5 block text-sm font-medium text-fg">
      {label}
    </label>
    {children}
    {hint && <p className="mt-1 text-xs text-fg-muted">{hint}</p>}
  </div>
);

interface TextFieldProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'id'> {
  label: string;
  /** Keeps the label in the accessibility tree while hiding it visually. */
  hideLabel?: boolean;
  /**
   * Extra label classes. Used to hide the label only once the container is
   * wide enough for the shared column header to name the field instead
   * (`@3xl:sr-only`), so a stacked card never shows a bare number box.
   */
  labelClassName?: string;
  hint?: string;
  wrapperClassName?: string;
  ref?: React.Ref<HTMLInputElement>;
}

export const TextField: React.FC<TextFieldProps> = ({
  label,
  hideLabel = false,
  labelClassName = '',
  hint,
  wrapperClassName,
  className = '',
  ref,
  ...rest
}) => {
  const id = useId();
  const hintId = `${id}-hint`;
  return (
    <div className={wrapperClassName}>
      <label
        htmlFor={id}
        className={`${hideLabel ? 'sr-only' : 'mb-1.5 block text-sm font-medium text-fg'} ${labelClassName}`}
      >
        {label}
      </label>
      <input
        id={id}
        ref={ref}
        aria-describedby={hint ? hintId : undefined}
        className={`${CONTROL_CLASS} ${className}`}
        {...rest}
      />
      {hint && (
        <p id={hintId} className="mt-1 text-xs text-fg-muted">
          {hint}
        </p>
      )}
    </div>
  );
};

interface TextAreaFieldProps extends Omit<React.TextareaHTMLAttributes<HTMLTextAreaElement>, 'id'> {
  label: string;
  hint?: string;
  wrapperClassName?: string;
}

export const TextAreaField: React.FC<TextAreaFieldProps> = ({
  label,
  hint,
  wrapperClassName,
  className = '',
  ...rest
}) => {
  const id = useId();
  return (
    <FieldShell label={label} hint={hint} htmlFor={id} className={wrapperClassName}>
      <textarea id={id} className={`${CONTROL_CLASS} resize-y ${className}`} {...rest} />
    </FieldShell>
  );
};

interface SelectFieldProps extends Omit<React.SelectHTMLAttributes<HTMLSelectElement>, 'id'> {
  label: string;
  hint?: string;
  wrapperClassName?: string;
}

export const SelectField: React.FC<SelectFieldProps> = ({
  label,
  hint,
  wrapperClassName,
  className = '',
  children,
  ...rest
}) => {
  const id = useId();
  return (
    <FieldShell label={label} hint={hint} htmlFor={id} className={wrapperClassName}>
      {/* A native select: the mobile OS pickers, typeahead and screen-reader
          support are better than anything a custom listbox would give here. */}
      <select id={id} className={`${CONTROL_CLASS} ${className}`} {...rest}>
        {children}
      </select>
    </FieldShell>
  );
};

interface NumberFieldProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'id' | 'value' | 'onChange' | 'type'> {
  label: string;
  /** Renders the label only to assistive tech. */
  hideLabel?: boolean;
  /** See TextField: used for `@3xl:sr-only`. */
  labelClassName?: string;
  value: number;
  onValueChange: (value: number) => void;
  wrapperClassName?: string;
}

/**
 * A number input that lets the field be genuinely empty while it is being
 * edited.
 *
 * The old inputs did `Number(e.target.value)` straight into state, so clearing
 * the field wrote 0 and immediately re-rendered a "0" the user then had to
 * select over before typing. The draft below holds the raw string while the
 * control is focused and is discarded on blur, so the model still only ever
 * sees a finite number.
 */
export const NumberField: React.FC<NumberFieldProps> = ({
  label,
  hideLabel = false,
  labelClassName = '',
  value,
  onValueChange,
  wrapperClassName,
  className = '',
  ...rest
}) => {
  const id = useId();
  const [draft, setDraft] = useState<string | null>(null);

  return (
    <div className={wrapperClassName}>
      <label
        htmlFor={id}
        className={`${hideLabel ? 'sr-only' : 'mb-1.5 block text-sm font-medium text-fg'} ${labelClassName}`}
      >
        {label}
      </label>
      <input
        id={id}
        type="number"
        inputMode="decimal"
        value={draft ?? String(value)}
        onChange={(event) => {
          const raw = event.target.value;
          setDraft(raw);
          if (raw === '') {
            onValueChange(0);
            return;
          }
          const parsed = Number(raw);
          if (Number.isFinite(parsed)) onValueChange(parsed);
        }}
        onBlur={(event) => {
          setDraft(null);
          rest.onBlur?.(event);
        }}
        className={`${CONTROL_CLASS} text-right tabular ${className}`}
        {...rest}
      />
    </div>
  );
};

export const buttonClass = {
  primary:
    'inline-flex items-center justify-center gap-2 rounded-lg bg-brand px-4 py-2.5 text-sm font-semibold text-brand-fg transition-colors hover:bg-brand-hover disabled:cursor-not-allowed disabled:opacity-60',
  secondary:
    'inline-flex items-center justify-center gap-2 rounded-lg border border-border-strong bg-surface px-4 py-2.5 text-sm font-medium text-fg transition-colors hover:bg-surface-sunken disabled:cursor-not-allowed disabled:opacity-60',
  success:
    'inline-flex items-center justify-center gap-2 rounded-lg bg-success px-4 py-2.5 text-sm font-semibold text-success-fg transition-opacity hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-60',
  danger:
    'inline-flex items-center justify-center gap-2 rounded-lg bg-danger px-4 py-2.5 text-sm font-semibold text-danger-fg transition-opacity hover:opacity-90',
  dangerGhost:
    'inline-flex items-center justify-center gap-2 rounded-lg border border-border-strong px-4 py-2.5 text-sm font-medium text-danger-text transition-colors hover:bg-danger-subtle',
  iconDanger:
    'grid size-9 place-items-center rounded-lg text-danger-text transition-colors hover:bg-danger-subtle disabled:cursor-not-allowed disabled:text-fg-muted disabled:hover:bg-transparent',
} as const;
